  1151  static void
  1152  deconstructNode(UA_Server *server, UA_Session *session,
  1153                  const UA_Node *node) {
  1154      /* Call the type-level destructor */
  1155      void *context = node->context; /* No longer needed after this function */
  1156      if(node->nodeClass == UA_NODECLASS_OBJECT ||
  1157         node->nodeClass == UA_NODECLASS_VARIABLE) {
  1158          const UA_Node *type = getNodeType(server, node);
  1159          if(type) {
  1160              const UA_NodeTypeLifecycle *lifecycle;
  1161              if(node->nodeClass == UA_NODECLASS_OBJECT)
  1162                  lifecycle = &((const UA_ObjectTypeNode*)type)->lifecycle;
  1163              else
  1164                  lifecycle = &((const UA_VariableTypeNode*)type)->lifecycle;
  1165              if(lifecycle->destructor)
  1166                  lifecycle->destructor(server,
  1167                                        &session->sessionId, session->sessionHandle,
  1168                                        &type->nodeId, type->context,
  1169                                        &node->nodeId, &context);
  1170              UA_Nodestore_release(server, type);
  1171          }
  1172      }
  1173
  1174      /* Call the global destructor */
  1175      if(server->config.nodeLifecycle.destructor)
  1176          server->config.nodeLifecycle.destructor(server, &session->sessionId,
  1177                                                  session->sessionHandle,
  1178                                                  &node->nodeId, context);
  1179  }
