  1185  static void
  1186  removeChildren(UA_Server *server, UA_Session *session,
  1187                 const UA_Node *node) {
  1188      /* Browse to get all children of the node */
  1189      UA_BrowseDescription bd;
  1190      UA_BrowseDescription_init(&bd);
  1191      bd.nodeId = node->nodeId;
  1192      bd.referenceTypeId = UA_NODEID_NUMERIC(0, UA_NS0ID_AGGREGATES);
  1193      bd.includeSubtypes = true;
  1194      bd.browseDirection = UA_BROWSEDIRECTION_FORWARD;
  1195      bd.nodeClassMask = UA_NODECLASS_OBJECT | UA_NODECLASS_VARIABLE | UA_NODECLASS_METHOD;
  1196      bd.resultMask = UA_BROWSERESULTMASK_NONE;
  1197
  1198      UA_BrowseResult br;
  1199      UA_BrowseResult_init(&br);
  1200      UA_UInt32 maxrefs = 0;
  1201      Operation_Browse(server, session, &maxrefs, &bd, &br);
  1202      if(br.statusCode != UA_STATUSCODE_GOOD)
  1203          return;
  1204
  1205      UA_DeleteNodesItem item;
  1206      item.deleteTargetReferences = true;
  1207
  1208      /* Remove every child */
  1209      for(size_t i = 0; i < br.referencesSize; ++i) {
  1210          UA_ReferenceDescription *rd = &br.references[i];
  1211          // check for self-reference to avoid endless loop
  1212          if(UA_NodeId_equal(&node->nodeId, &rd->nodeId.nodeId))
  1213              continue;
  1214          item.nodeId = rd->nodeId.nodeId;
  1215          UA_StatusCode retval;
  1216          deleteNodeOperation(server, session, NULL, &item, &retval);
  1217      }
  1218
  1219      UA_BrowseResult_deleteMembers(&br);
  1220  }
