  1222  static void
  1223  removeDeconstructedNode(UA_Server *server, UA_Session *session,
  1224                          const UA_Node *node, UA_Boolean removeTargetRefs) {
  1225      /* Remove all children of the node */
  1226      removeChildren(server, session, node);
  1227
  1228      /* Remove references to the node (not the references going out, as the node
  1229       * will be deleted anyway) */
  1230      if(removeTargetRefs)
  1231          removeIncomingReferences(server, session, node);
  1232
  1233      /* Remove the node in the nodestore */
  1234      UA_Nodestore_remove(server, &node->nodeId);
  1235  }
