  1237  static void
  1238  deleteNodeOperation(UA_Server *server, UA_Session *session, void *context,
  1239                      const UA_DeleteNodesItem *item, UA_StatusCode *result) {
  1240      /* Do not check access for server */
  1241      if(session != &adminSession && server->config.accessControl.allowDeleteNode &&
  1242         !server->config.accessControl.allowDeleteNode(&session->sessionId, session->sessionHandle, item)) {
  1243          *result = UA_STATUSCODE_BADUSERACCESSDENIED;
  1244          return;
  1245      }
  1246
  1247      const UA_Node *node = UA_Nodestore_get(server, &item->nodeId);
  1248      if(!node) {
  1249          *result = UA_STATUSCODE_BADNODEIDUNKNOWN;
  1250          return;
  1251      }
  1252
  1253      if(UA_Node_hasSubTypeOrInstances(node)) {
  1254          UA_LOG_INFO_SESSION(server->config.logger, session,
  1255                              "Delete Nodes: Cannot delete a type node "
  1256                              "with active instances or subtypes");
  1257          UA_Nodestore_release(server, node);
  1258          *result = UA_STATUSCODE_BADINTERNALERROR;
  1259          return;
  1260      }
  1261
  1262      /* TODO: Check if the information model consistency is violated */
  1263      /* TODO: Check if the node is a mandatory child of a parent */
  1264
  1265      deconstructNode(server, session, node);
  1266      removeDeconstructedNode(server, session, node, item->deleteTargetReferences);
  1267      UA_Nodestore_release(server, node);
  1268  }
