   320  static UA_StatusCode
   321  UA_NodeMap_insertNode(void *context, UA_Node *node,
   322                        UA_NodeId *addedNodeId) {
   323      UA_NodeMap *ns = (UA_NodeMap*)context;
   324      BEGIN_CRITSECT(ns);
   325      if(ns->size * 3 <= ns->count * 4) {
   326          if(expand(ns) != UA_STATUSCODE_GOOD) {
   327              END_CRITSECT(ns);
   328              return UA_STATUSCODE_BADINTERNALERROR;
   329          }
   330      }
   331
   332      UA_NodeMapEntry **slot;
   333      if(node->nodeId.identifierType == UA_NODEIDTYPE_NUMERIC &&
   334              node->nodeId.identifier.numeric == 0) {
   335          /* create a random nodeid */
   336          /* start at least with 50,000 to make sure we don not conflict with nodes from the spec */
   337          /* E.g. adding a nodeset will create children while there are still other nodes which need to be created */
   338          /* Thus the node id's may collide */
   339          UA_UInt32 identifier = 50000 + ns->count+1; // start value
   340          UA_UInt32 size = ns->size;
   341          UA_UInt32 increase = mod2(ns->count+1, size);
   342          while(true) {
   343              node->nodeId.identifier.numeric = identifier;
   344              slot = findFreeSlot(ns, &node->nodeId);
   345              if(slot)
   346                  break;
   347              identifier += increase;
   348              if(identifier >= size)
   349                  identifier -= size;
   350          }
   351      } else {
   352          slot = findFreeSlot(ns, &node->nodeId);
   353          if(!slot) {
   354              deleteEntry(container_of(node, UA_NodeMapEntry, node));
   355              END_CRITSECT(ns);
   356              return UA_STATUSCODE_BADNODEIDEXISTS;
   357          }
   358      }
   359
   360      *slot = container_of(node, UA_NodeMapEntry, node);
   361      ++ns->count;
   362      UA_assert(&(*slot)->node == node);
   363
   364      UA_StatusCode retval = UA_STATUSCODE_GOOD;
   365      if(addedNodeId) {
   366          retval = UA_NodeId_copy(&node->nodeId, addedNodeId);
   367          if(retval != UA_STATUSCODE_GOOD)
   368              clearSlot(ns, slot);
   369      }
   370
   371      END_CRITSECT(ns);
   372      return retval;
   373  }
