   375  static UA_StatusCode
   376  UA_NodeMap_replaceNode(void *context, UA_Node *node) {
   377      UA_NodeMap *ns = (UA_NodeMap*)context;
   378      BEGIN_CRITSECT(ns);
   379      UA_NodeMapEntry **slot = findOccupiedSlot(ns, &node->nodeId);
   380      if(!slot) {
   381          END_CRITSECT(ns);
   382          return UA_STATUSCODE_BADNODEIDUNKNOWN;
   383      }
   384      UA_NodeMapEntry *newEntryContainer = container_of(node, UA_NodeMapEntry, node);
   385      if(*slot != newEntryContainer->orig) {
   386          /* The node was updated since the copy was made */
   387          deleteEntry(newEntryContainer);
   388          END_CRITSECT(ns);
   389          return UA_STATUSCODE_BADINTERNALERROR;
   390      }
   391      (*slot)->deleted = true;
   392      cleanupEntry(*slot);
   393      *slot = newEntryContainer;
   394      END_CRITSECT(ns);
   395      return UA_STATUSCODE_GOOD;
   396  }
