   398  static void
   399  UA_NodeMap_iterate(void *context, void *visitorContext,
   400                     UA_NodestoreVisitor visitor) {
   401      UA_NodeMap *ns = (UA_NodeMap*)context;
   402      BEGIN_CRITSECT(ns);
   403      for(UA_UInt32 i = 0; i < ns->size; ++i) {
   404          if(ns->entries[i] > UA_NODEMAP_TOMBSTONE) {
   405              END_CRITSECT(ns);
   406              UA_NodeMapEntry *entry = ns->entries[i];
   407              entry->refCount++;
   408              visitor(visitorContext, &entry->node);
   409              entry->refCount--;
   410              cleanupEntry(entry);
   411              BEGIN_CRITSECT(ns);
   412          }
   413      }
   414      END_CRITSECT(ns);
   415  }
